import React, { useEffect, useState } from 'react';
import { db } from '../firebase-config';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { auth } from '../firebase-config';
import { PieChart, Pie, Cell, Tooltip } from 'recharts'; // Import des composants pour le diagramme
import './Profile.css'; // Import des styles pour les cartes

const Profile = () => {
  const [activities, setActivities] = useState([]);
  const [totalRemainingSadaqa, setTotalRemainingSadaqa] = useState(0);
  const [gainsData, setGainsData] = useState([]); // Données pour le diagramme

  useEffect(() => {
    const fetchActivities = async () => {
      try {
        const user = auth.currentUser;
        if (user) {
          const activitiesCollectionRef = collection(db, 'activities');
          const q = query(activitiesCollectionRef, where('userId', '==', user.uid));
          const querySnapshot = await getDocs(q);

          const fetchedActivities = [];
          let sadaqaRemaining = 0;
          const gainsByDay = [];

          querySnapshot.forEach((doc) => {
            const data = doc.data();
            fetchedActivities.push({ id: doc.id, ...data });

            // Ajouter les gains au diagramme
            if (data.totalGains) {
              gainsByDay.push({
                name: new Date(data.date).toLocaleDateString('fr-FR', {
                  weekday: 'long',
                  day: 'numeric',
                  month: 'numeric',
                  year: 'numeric',
                }),
                value: data.totalGains,
              });
            }

            // Calculer le montant restant pour les Sadaqa
            if (data.sadaqaStatus === 'Pas encore' || data.sadaqaStatus === 'Partiellement payé') {
              const remaining = data.sadaqaAmount - (data.sadaqaPaid || 0);
              sadaqaRemaining += remaining;
            }
          });

          setActivities(fetchedActivities);
          setTotalRemainingSadaqa(sadaqaRemaining);
          setGainsData(gainsByDay);
        }
      } catch (error) {
        console.error('Erreur lors du chargement des activités :', error);
      }
    };

    fetchActivities();
  }, []);

  const COLORS = ['#6a1b9a', '#283593', '#d32f2f', '#ff9800', '#4caf50']; // Couleurs pour le diagramme

  return (
    <div className="container mt-5">
      <h1 className="text-center mb-4">👤 Profil</h1>

      {/* Diagramme des gains */}
      <div className="card mb-4">
        <div className="card-body">
          <h3 className="card-title text-center">📊 Progression des gains par jour</h3>
          <div className="chart-container">
            <PieChart width={400} height={400}>
              <Pie
                data={gainsData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                outerRadius={150}
                fill="#8884d8"
                label
              >
                {gainsData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </div>
        </div>
      </div>

      {/* Afficher le montant total restant pour les Sadaqa */}
      <div className="card mt-4 sadaqa-card">
        <div className="card-body text-center">
          <h3 className="card-title">🤲 Sadaqa restante</h3>
          <p className="sadaqa-amount">
            Montant total restant : <strong>{totalRemainingSadaqa.toFixed(2)} Dhs</strong>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Profile;
